{
  "verdict": "request_changes",
  "summary": "Catalog caching does not invalidate entries after an update, causing stale prices and violating the contract that every later price or quote call must reflect the new price.",
  "findings": [
    {
      "finding_id": "C01",
      "file": "candidate.py",
      "line_start": 16,
      "line_end": 19,
      "severity": "high",
      "description": "Missing cache invalidation in update_price. The cache entry for the updated SKU is never cleared, so subsequent price() calls may return the stale cached value and not reflect the new price set by update_price.",
      "evidence": "Example: catalog = Catalog({\"a\": 100}); catalog.price(\"a\")  # caches 100\n    catalog.update_price(\"a\", 200);\n    catalog.price(\"a\")  # returns 100 instead of 200, violating the spec."
    }
  ]
}
